const base = pm.collectionVariables.get('baseUrl') + '/api/v1/detalles-plan/';
const tk = pm.collectionVariables.get('tokenAdmin');
const mp = Number(pm.collectionVariables.get('mp_CONC'));
const lineas = [pm.collectionVariables.get('linea_A1'), pm.collectionVariables.get('linea_A2')];
const codes = [];
lineas.forEach((l) => {
  pm.sendRequest({ url: base + l + '/consumos', method: 'POST',
    header: { 'Authorization': 'Bearer ' + tk, 'Content-Type': 'application/json' },
    body: { mode: 'raw', raw: JSON.stringify({ idMateriaPrima: mp, cantidadReal: 6 }) } },
    (err, res) => {
      codes.push(err ? 0 : res.code);
      if (codes.length === lineas.length) {
        pm.test("CP-14 un 201 y un 409", () => pm.expect(codes.slice().sort()).to.eql([201, 409]));
      }
    });
});
